// Simple IndexedDB wrapper for the shared file
const getSharedFile = (): Promise<File | null> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open('SharedFilesDB', 1);
    request.onerror = () => reject(request.error);
    request.onsuccess = (event: any) => {
      const db = event.target.result;
      if (!db.objectStoreNames.contains('files')) {
        resolve(null);
        return;
      }
      const transaction = db.transaction('files', 'readonly');
      const store = transaction.objectStore('files');
      const getRequest = store.get('shared-audio');
      getRequest.onsuccess = () => resolve(getRequest.result || null);
      getRequest.onerror = () => reject(getRequest.error);
    };
  });
};

const clearSharedFileLocal = (): Promise<void> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open('SharedFilesDB', 1);
    request.onerror = () => reject(request.error);
    request.onsuccess = (event: any) => {
      const db = event.target.result;
      if (!db.objectStoreNames.contains('files')) {
        resolve();
        return;
      }
      const transaction = db.transaction('files', 'readwrite');
      const store = transaction.objectStore('files');
      const deleteRequest = store.delete('shared-audio');
      deleteRequest.onsuccess = () => resolve();
      deleteRequest.onerror = () => reject(deleteRequest.error);
    };
  });
};

const resolveSharedAudioMimeType = (name: string, declaredType: string, bytes: Uint8Array) => {
  const normalizedDeclaredType = declaredType.toLowerCase().trim();
  const normalizedName = name.toLowerCase();
  const hasPrefix = (...values: number[]) => values.every((value, index) => bytes[index] === value);

  if (hasPrefix(0x4f, 0x67, 0x67, 0x53)) return 'audio/ogg; codecs=opus';
  if (hasPrefix(0x1a, 0x45, 0xdf, 0xa3)) return 'audio/webm; codecs=opus';
  if (hasPrefix(0x52, 0x49, 0x46, 0x46) && bytes[8] === 0x57 && bytes[9] === 0x41 && bytes[10] === 0x56 && bytes[11] === 0x45) return 'audio/wav';
  if (hasPrefix(0x49, 0x44, 0x33) || (bytes[0] === 0xff && (bytes[1] & 0xe0) === 0xe0)) return 'audio/mpeg';
  if (normalizedName.endsWith('.opus') || normalizedName.endsWith('.ogg')) return 'audio/ogg; codecs=opus';
  if (normalizedName.endsWith('.webm')) return 'audio/webm; codecs=opus';
  if (normalizedName.endsWith('.m4a')) return 'audio/mp4';
  if (normalizedName.endsWith('.mp3')) return 'audio/mpeg';
  if (normalizedDeclaredType.startsWith('audio/')) return normalizedDeclaredType;
  return 'audio/ogg; codecs=opus';
};

const normalizeSharedAudioFile = async (file: File) => {
  const header = new Uint8Array(await file.slice(0, 16).arrayBuffer());
  const type = resolveSharedAudioMimeType(file.name, file.type || '', header);
  return new File([file], file.name || 'audio-compartilhado.ogg', {
    type,
    lastModified: file.lastModified || Date.now()
  });
};

const getNativeSharedFile = async (): Promise<File | null> => {
  const nativeShare = (window as any).NativeShare;
  if (!nativeShare || typeof nativeShare.getSharedFile !== 'function') return null;

  const rawPayload = nativeShare.getSharedFile();
  if (!rawPayload) return null;

  const payload = JSON.parse(rawPayload) as { name?: string; type?: string; data?: string };
  if (!payload.data) return null;

  const binary = window.atob(payload.data);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index);
  }

  const type = resolveSharedAudioMimeType(payload.name || '', payload.type || '', bytes);
  const file = new File(
    [bytes],
    payload.name || 'audio-compartilhado.ogg',
    { type }
  );

  return file;
};

type NativeAudioPlaybackState = {
  status: 'idle' | 'preparing' | 'playing' | 'paused' | 'completed' | 'error';
  positionMs: number;
  durationMs: number;
  error?: string;
};

const initialNativePlaybackState: NativeAudioPlaybackState = {
  status: 'idle',
  positionMs: 0,
  durationMs: 0
};

const getNativeShareBridge = () => (window as any).NativeShare;

const stopWebViewAudioFallbackSources = () => {
  const audioWindow = window as typeof window & { __evolucaoStopAudioFallbackSources?: () => void };
  audioWindow.__evolucaoStopAudioFallbackSources?.();
};

const clearSharedAudioSources = async () => {
  stopWebViewAudioFallbackSources();
  await clearSharedFileLocal().catch(error => console.warn('Erro ao limpar áudio compartilhado do navegador:', error));
  const nativeShare = getNativeShareBridge();
  if (nativeShare && typeof nativeShare.clearSharedFile === 'function') {
    nativeShare.clearSharedFile();
  }
};

const formatPlaybackTime = (milliseconds: number) => {
  const totalSeconds = Math.max(0, Math.floor(milliseconds / 1000));
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  return `${minutes}:${String(seconds).padStart(2, '0')}`;
};

const getAudioDurationFromFile = async (file: File): Promise<number> => {
  const objectUrl = URL.createObjectURL(file);

  try {
    const duration = await new Promise<number>((resolve) => {
      const audio = document.createElement('audio');

      const finalize = (value: number) => {
        audio.removeAttribute('src');
        audio.load();
        resolve(Number.isFinite(value) ? value : 0);
      };

      audio.preload = 'metadata';
      audio.onloadedmetadata = () => finalize(audio.duration || 0);
      audio.onerror = () => finalize(0);
      audio.src = objectUrl;
    });

    return duration;
  } finally {
    URL.revokeObjectURL(objectUrl);
  }
};

const isGoogleReconnectNeededMessage = (message: string) => {
  const normalized = message.toLowerCase();
  return (
    normalized.includes('sessão do google expirou') ||
    normalized.includes('autenticação do google') ||
    normalized.includes('authenticação do google') ||
    normalized.includes('autenticação google') ||
    normalized.includes('insufficient_scopes') ||
    normalized.includes('insufficient scopes') ||
    normalized.includes('unauthenticated') ||
    normalized.includes('credentials') ||
    normalized.includes('401')
  );
};

const SHARE_TARGET_AUTH_RECOVERY_KEY = 'share-target:resume-after-google-auth';

type ShareTargetAuthRecovery = {
  patientId: string;
  templateId: string;
  sessionDate: string;
  sessionTime: string;
};

const readShareTargetAuthRecovery = (): ShareTargetAuthRecovery | null => {
  try {
    const raw = sessionStorage.getItem(SHARE_TARGET_AUTH_RECOVERY_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as Partial<ShareTargetAuthRecovery>;
    if (!parsed.patientId) return null;
    return {
      patientId: parsed.patientId,
      templateId: parsed.templateId || '',
      sessionDate: parsed.sessionDate || new Date().toISOString().split('T')[0],
      sessionTime: parsed.sessionTime || '',
    };
  } catch {
    return null;
  }
};


export default function ShareTarget() {
  const navigate = useNavigate();
  const { user, googleAccessToken, googleAccessTokenIssuedAt, googleGrantedScopes, setGoogleAccessToken, subscriptionPlan } = useAuthStore();
  const authRecoveryRef = useRef(readShareTargetAuthRecovery());
  const [patients, setPatients] = useState<any[]>([]);
  const [templates, setTemplates] = useState<any[]>([]);
  const [selectedPatientId, setSelectedPatientId] = useState<string>(authRecoveryRef.current?.patientId || '');
  const [selectedTemplateId, setSelectedTemplateId] = useState<string>(authRecoveryRef.current?.templateId || '');
  const [sessionDate, setSessionDate] = useState(authRecoveryRef.current?.sessionDate || new Date().toISOString().split('T')[0]);
  const [sessionTime, setSessionTime] = useState(() => {
    if (authRecoveryRef.current?.sessionTime) return authRecoveryRef.current.sessionTime;
    const saved = localStorage.getItem('evolucao-clinica:default-session-time');
    if (saved) return saved;
    const now = new Date();
    return `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
  });

  const handleSessionTimeChange = (time: string) => {
    setSessionTime(time);
    localStorage.setItem('evolucao-clinica:default-session-time', time);
  };
  const [audioFile, setAudioFile] = useState<File | null>(null);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const [usesNativeSharedAudio, setUsesNativeSharedAudio] = useState(false);
  const [audioPlaybackError, setAudioPlaybackError] = useState(false);
  const [audioMetadataUnavailable, setAudioMetadataUnavailable] = useState(false);
  const [nativePlayback, setNativePlayback] = useState<NativeAudioPlaybackState>(initialNativePlaybackState);
  const [nativePlaybackRequested, setNativePlaybackRequested] = useState(false);
  const nativePauseRequestedRef = useRef(false);
  const audioElementRef = useRef<HTMLAudioElement | null>(null);
  const [installedAppInfo] = useState(getInstalledAppInfo);
  const [status, setStatus] = useState<'loading' | 'idle' | 'processing' | 'success' | 'error'>('loading');
  const [errorMessage, setErrorMessage] = useState('');
  const [isReauthenticating, setIsReauthenticating] = useState(false);

  // Estados para edição da evolução recém-processada no modal
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [modalText, setModalText] = useState('');
  const [modalOriginalTranscription, setModalOriginalTranscription] = useState('');
  const [modalEvolutionId, setModalEvolutionId] = useState<string | null>(null);
  const [modalTemplateId, setModalTemplateId] = useState('');
  const [modalSaving, setModalSaving] = useState(false);
  const [modalConverting, setModalConverting] = useState(false);
  const [modalError, setModalError] = useState('');
  const hasClinicalAccess = Boolean(googleAccessToken) && hasGoogleScopes(googleGrantedScopes, GOOGLE_SCOPE_SETS.clinicalDocs);
  const hasFreshClinicalAccess = hasClinicalAccess && isGoogleAccessTokenFresh(googleAccessToken, googleAccessTokenIssuedAt);
  const needsGoogleReconnect = !hasClinicalAccess || isGoogleReconnectNeededMessage(errorMessage) || isGoogleReconnectNeededMessage(modalError);
  const nativeShare = getNativeShareBridge();
  const hasNativeAudioPlayback = Boolean(nativeShare && typeof nativeShare.playSharedFile === 'function');
  const useNativeAudioPlayer = usesNativeSharedAudio && hasNativeAudioPlayback;
  const needsNativePauseUpdate = installedAppInfo.platform === 'android'
    && Boolean(installedAppInfo.versionCode && installedAppInfo.versionCode < 75);

  useEffect(() => {
    if (hasFreshClinicalAccess) {
      sessionStorage.removeItem(SHARE_TARGET_AUTH_RECOVERY_KEY);
    }
  }, [hasFreshClinicalAccess]);

  // O áudio compartilhado e seus dados de processamento ainda podem estar em
  // memória. Impedir o pull-to-refresh evita que sejam perdidos acidentalmente.
  useEffect(() => {
    const previousHtmlOverscroll = document.documentElement.style.overscrollBehaviorY;
    const previousBodyOverscroll = document.body.style.overscrollBehaviorY;
    const nativeAppInfoBridge = (window as typeof window & {
      NativeAppInfoBridge?: { setPullToRefreshEnabled?: (enabled: boolean) => void };
    }).NativeAppInfoBridge;
    let touchStartY = 0;
    document.documentElement.style.overscrollBehaviorY = 'none';
    document.body.style.overscrollBehaviorY = 'none';
    nativeAppInfoBridge?.setPullToRefreshEnabled?.(false);

    const getScrollableAncestor = (target: EventTarget | null) => {
      let element = target instanceof Element ? target : null;
      while (element && element !== document.body) {
        const overflowY = window.getComputedStyle(element).overflowY;
        if ((overflowY === 'auto' || overflowY === 'scroll') && element.scrollHeight > element.clientHeight) {
          return element;
        }
        element = element.parentElement;
      }
      return null;
    };

    const onTouchStart = (event: TouchEvent) => {
      touchStartY = event.touches[0]?.clientY || 0;
    };

    const onTouchMove = (event: TouchEvent) => {
      const currentY = event.touches[0]?.clientY || 0;
      const isPullingDown = currentY > touchStartY;
      const pageAtTop = Math.max(window.scrollY, document.documentElement.scrollTop, document.body.scrollTop) <= 0;
      const scrollableAncestor = getScrollableAncestor(event.target);
      const innerContentCanScrollUp = Boolean(scrollableAncestor && scrollableAncestor.scrollTop > 0);

      if (isPullingDown && pageAtTop && !innerContentCanScrollUp && event.cancelable) {
        event.preventDefault();
      }
    };

    document.addEventListener('touchstart', onTouchStart, { passive: true, capture: true });
    document.addEventListener('touchmove', onTouchMove, { passive: false, capture: true });

    return () => {
      nativeAppInfoBridge?.setPullToRefreshEnabled?.(true);
      document.removeEventListener('touchstart', onTouchStart, true);
      document.removeEventListener('touchmove', onTouchMove, true);
      document.documentElement.style.overscrollBehaviorY = previousHtmlOverscroll;
      document.body.style.overscrollBehaviorY = previousBodyOverscroll;
    };
  }, []);

  useEffect(() => {
    const loadData = async () => {
      try {
        // Load patients
        let patientsData: any[] = [];
        if (user) {
          const { data, error } = await supabase
            .from('patients')
            .select('*')
            .eq('professional_id', user.id)
            .order('full_name');
          if (error) throw error;
          patientsData = data || [];
        }
        setPatients(patientsData);

        const { data: templatesData, error: templatesError } = await supabase
          .from('evolution_templates')
          .select('id, name')
          .order('name');
        if (templatesError) {
          console.warn('Não foi possível carregar os templates de evolução:', templatesError);
        } else {
          setTemplates(templatesData || []);
        }

        // Load shared file
        const localSharedFile = await getSharedFile();
        const nativeSharedFile = localSharedFile ? null : await getNativeSharedFile();
        const file = localSharedFile || nativeSharedFile;
        if (file && file.size > 0) {
          const normalizedFile = await normalizeSharedAudioFile(file);
          setAudioFile(normalizedFile);
          setAudioUrl(URL.createObjectURL(normalizedFile));
          setUsesNativeSharedAudio(Boolean(nativeSharedFile));
          setNativePlayback(initialNativePlaybackState);
          setNativePlaybackRequested(false);
          nativePauseRequestedRef.current = false;
          setStatus('idle');
        } else if (file) {
          setStatus('error');
          setErrorMessage('O áudio recebido está vazio. Compartilhe novamente a nota de voz pelo WhatsApp.');
        } else {
          setStatus('error');
          setErrorMessage('Nenhum áudio recebido. Tente compartilhar novamente a partir do WhatsApp.');
        }
      } catch (error: any) {
        console.error("Error loading shared file:", error);
        setStatus('error');
        setErrorMessage('Erro ao carregar: ' + (error?.message || error?.name || JSON.stringify(error)));
      }
    };
    loadData();
  }, [user]);

  useEffect(() => {
    return () => {
      if (audioUrl) URL.revokeObjectURL(audioUrl);
    };
  }, [audioUrl]);

  useEffect(() => {
    const pauseEveryPlayer = (updateInterface = true) => {
      const audio = audioElementRef.current;
      if (audio && !audio.paused) audio.pause();
      stopWebViewAudioFallbackSources();
      getNativeShareBridge()?.pauseSharedFile?.();
      nativePauseRequestedRef.current = true;
      if (updateInterface) {
        setNativePlaybackRequested(false);
        setNativePlayback(current => current.status === 'playing' || current.status === 'preparing'
          ? { ...current, status: 'paused' }
          : current);
      }
    };

    const handlePageHide = () => pauseEveryPlayer();
    const handleVisibilityChange = () => {
      if (document.visibilityState === 'hidden') pauseEveryPlayer();
    };

    window.addEventListener('pagehide', handlePageHide);
    document.addEventListener('visibilitychange', handleVisibilityChange);

    return () => {
      window.removeEventListener('pagehide', handlePageHide);
      document.removeEventListener('visibilitychange', handleVisibilityChange);
      pauseEveryPlayer(false);
      // Ao sair desta rota, liberar a fonte nativa impede que uma instância de
      // player de versões anteriores continue tocando em segundo plano.
      getNativeShareBridge()?.clearSharedFile?.();
    };
  }, []);

  useEffect(() => {
    const handleNativePlaybackState = (event: Event) => {
      const detail = (event as CustomEvent<NativeAudioPlaybackState>).detail;
      if (!detail?.status) return;

      if (detail.status === 'playing' && nativePauseRequestedRef.current) {
        getNativeShareBridge()?.pauseSharedFile?.();
        setNativePlayback({ ...detail, status: 'paused' });
        setNativePlaybackRequested(false);
        return;
      }

      if (detail.status === 'paused' || detail.status === 'completed' || detail.status === 'error') {
        nativePauseRequestedRef.current = false;
      }
      setNativePlayback(detail);
      setNativePlaybackRequested(detail.status === 'playing' || detail.status === 'preparing');
    };

    window.addEventListener('native-shared-audio-state', handleNativePlaybackState);
    return () => window.removeEventListener('native-shared-audio-state', handleNativePlaybackState);
  }, []);

  const handleNativePlaybackToggle = () => {
    const bridge = getNativeShareBridge();
    if (!bridge) return;

    const shouldPause = nativePlaybackRequested
      || nativePlayback.status === 'playing'
      || nativePlayback.status === 'preparing';

    if (shouldPause) {
      nativePauseRequestedRef.current = true;
      bridge.pauseSharedFile?.();
      setNativePlaybackRequested(false);
      setNativePlayback(current => ({ ...current, status: 'paused' }));
      return;
    }

    const accepted = bridge.playSharedFile?.();
    if (accepted === false) {
      setNativePlayback({
        ...initialNativePlaybackState,
        status: 'error',
        error: 'O arquivo compartilhado não está mais disponível para reprodução.'
      });
      return;
    }

    // Alguns WebViews atrasam o evento enviado pelo Android. Atualizar o estado
    // de forma otimista mantém o botão de pausa disponível desde o primeiro toque.
    nativePauseRequestedRef.current = false;
    setNativePlaybackRequested(true);
    setNativePlayback(current => ({ ...current, status: 'playing', error: '' }));
  };

  const handleNativePlaybackSeek = (positionMs: number) => {
    getNativeShareBridge()?.seekSharedFile?.(positionMs);
    setNativePlayback(current => ({ ...current, positionMs }));
  };

  const handlePatientChange = (patientId: string) => {
    setSelectedPatientId(patientId);
    const patient = patients.find(item => item.id === patientId);
    setSelectedTemplateId(patient?.default_template_id || '');
  };

  const handleCancel = async () => {
    nativePauseRequestedRef.current = false;
    setNativePlaybackRequested(false);
    sessionStorage.removeItem(SHARE_TARGET_AUTH_RECOVERY_KEY);
    await clearSharedAudioSources();
    navigate('/painel/dashboard');
  };

  const handleReauthenticate = async (prompt: 'none' | 'consent' = 'consent') => {
    setIsReauthenticating(true);
    try {
      sessionStorage.setItem(SHARE_TARGET_AUTH_RECOVERY_KEY, JSON.stringify({
        patientId: selectedPatientId,
        templateId: selectedTemplateId,
        sessionDate,
        sessionTime,
      } satisfies ShareTargetAuthRecovery));
      const { error } = await requestGoogleOAuth({
        requiredScopes: 'clinicalDocs',
        currentGrantedScopes: googleGrantedScopes,
        redirectTo: getCurrentGoogleOAuthRedirectUrl(),
        prompt,
        loginHint: user?.email || undefined
      });
      if (error) throw error;
    } catch (error) {
      console.error("Reauthentication error:", error);
      setGoogleAccessToken(null);
      setErrorMessage('Não foi possível renovar automaticamente a autenticação do Google. Use o botão abaixo para conectar novamente.');
      setStatus('error');
    } finally {
      setIsReauthenticating(false);
    }
  };

  const handleOpenModal = () => {
    setIsModalOpen(true);
    setModalError('');
    if (!modalEvolutionId || !modalText.trim()) {
      setModalError('A evolução recém-processada não está disponível para edição. Volte ao paciente e abra a evolução desejada.');
    }
  };

  const handleSaveModalText = async () => {
    const patient = patients.find(p => p.id === selectedPatientId);
    if (!patient || !patient.google_doc_id || !modalEvolutionId || !hasClinicalAccess || !googleAccessToken) {
      setModalError('Renove a conexão com o Google para salvar esta evolução de forma sincronizada.');
      return;
    }
    setModalSaving(true);
    setModalError('');
    try {
      const { error } = await supabase.from('evolutions').update({
        transcription_text: modalText,
        template_id: modalTemplateId || null,
        updated_at: new Date().toISOString(),
      }).eq('id', modalEvolutionId);
      if (error) throw error;
      await replaceEvolutionInGoogleDoc(googleAccessToken, patient.google_doc_id, modalEvolutionId, modalText);
      await showAlert("Evolução atualizada com sucesso na plataforma e no Google Docs!", {
        title: "Evolução Atualizada",
        variant: "success",
        icon: "success"
      });
      setIsModalOpen(false);
    } catch (err: any) {
      console.error("Erro ao salvar prontuário:", err);
      let msg = err.message || "Erro desconhecido ao salvar prontuário.";
      if (msg.includes("INSUFFICIENT_SCOPES")) {
        msg = "Sua conta Google está conectada, mas ainda não liberou as permissões clínicas completas. Renove a autenticação para aprovar o acesso ao Google Drive e Docs.";
      } else if (msg.includes("UNAUTHENTICATED") || msg.includes("401")) {
        msg = "Sua sessão do Google expirou. Por favor, renove sua autenticação.";
        setGoogleAccessToken(null);
      }
      setModalError(msg);
    } finally {
      setModalSaving(false);
    }
  };

  const handleConvertModalEvolution = async () => {
    if (!modalText.trim()) return;
    if (!modalOriginalTranscription.trim()) {
      setModalError('A transcrição original desta evolução não está disponível para conversão.');
      return;
    }
    setModalConverting(true);
    setModalError('');
    try {
      const converted = await convertEvolutionToTemplate(modalOriginalTranscription, modalTemplateId || null);
      setModalText(converted);
    } catch (err: any) {
      setModalError(err.message || 'Não foi possível converter a evolução para o modelo escolhido.');
    } finally {
      setModalConverting(false);
    }
  };

  const handleProcess = async () => {
    if (!audioFile || !selectedPatientId) return;

    if (audioFile.size === 0) {
      setErrorMessage('O áudio recebido está vazio. Compartilhe novamente a nota de voz pelo WhatsApp.');
      setStatus('error');
      return;
    }

    const patient = patients.find(p => p.id === selectedPatientId);
    if (!patient || !patient.google_doc_id) {
      setErrorMessage('Paciente selecionado não possui um Google Doc vinculado.');
      setStatus('error');
      return;
    }

    if (!hasFreshClinicalAccess) {
      setErrorMessage('');
      setStatus('idle');
      const wasPreviouslyConnected = hasGoogleScopes(googleGrantedScopes, GOOGLE_SCOPE_SETS.clinicalDocs);
      await handleReauthenticate(wasPreviouslyConnected ? 'none' : 'consent');
      return;
    }

    try {
      // Valida o token antes da transcrição para nunca descobrir a expiração
      // somente depois do processamento clínico já ter sido executado.
      if (navigator.onLine) {
        await validateGoogleDocAccess(googleAccessToken, patient.google_doc_id);
      }
    } catch (error: any) {
      const message = error?.message || String(error);
      if (isGoogleReconnectNeededMessage(message)) {
        setGoogleAccessToken(null);
        setErrorMessage('');
        setStatus('idle');
        await handleReauthenticate(message.includes('INSUFFICIENT_SCOPES') ? 'consent' : 'none');
        return;
      }

      setErrorMessage(`Não foi possível validar o acesso ao prontuário: ${message}`);
      setStatus('error');
      return;
    }

    setStatus('processing');
    setErrorMessage('');

    const estimatedAudioDuration = await getAudioDurationFromFile(audioFile);
    const safeAudioDuration = Math.max(1, Math.round(estimatedAudioDuration || 0));
    const evolutionId = uuidv4();

    const evolutionData = {
      id: evolutionId,
      professional_id: user?.id || '',
      patient_id: selectedPatientId,
      session_date: sessionDate,
      session_time: sessionTime,
      audio_url: '',
      transcription_status: 'processing',
      transcription_text: '',
      google_doc_append_status: 'pending',
      audio_duration_seconds: safeAudioDuration,
      template_id: selectedTemplateId || null,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString()
    };

    try {
      if (!navigator.onLine) {
        throw new Error("offline");
      }

      setStatus('processing');
      setErrorMessage("Etapa 1/4: Salvando registro inicial...");

      // 1. Save initial state
      const { error: insertError } = await supabase
        .from('evolutions')
        .upsert(evolutionData);
      if (insertError) throw insertError;

      // 2. Transcribe with AI
      setErrorMessage("Etapa 2/4: Transcrevendo áudio com IA...");
      let mimeType = audioFile.type;

      if (!mimeType || mimeType === 'application/octet-stream') {
        mimeType = 'audio/ogg'; // WhatsApp PWA costuma vir com esse mimeType genérico
      }

      const transcription = await transcribeAudio({
        audioBlob: audioFile,
        mimeType,
        audioDuration: safeAudioDuration,
        subscriptionPlan,
        evolutionId,
        audioKey: evolutionId,
        onRetry: (attempt, delay, isFallback) => {
          setErrorMessage(`Etapa 2/4: Retentativa IA ${attempt}/3 em ${Math.round(delay/1000)}s...`);
        }
      });

      if (!transcription) throw new Error("A IA retornou um texto vazio.");

      const { error: originalSaveError } = await supabase
        .from('evolutions')
        .update({
          original_transcription_text: transcription,
          updated_at: new Date().toISOString()
        })
        .eq('id', evolutionId);
      if (originalSaveError) throw originalSaveError;

      let evolutionText = transcription;
      if (selectedTemplateId) {
        setErrorMessage('Etapa 3/5: Aplicando o template selecionado...');
        evolutionText = await convertEvolutionToTemplate(transcription, selectedTemplateId);
      }

      // 3. Append to Google Docs
      setErrorMessage(selectedTemplateId
        ? 'Etapa 4/5: Inserindo no prontuário (Google Docs)...'
        : 'Etapa 3/4: Inserindo no prontuário (Google Docs)...');
      await appendToGoogleDoc(
        googleAccessToken,
        patient.google_doc_id,
        sessionDate,
        evolutionText,
        {
          sessionTime,
          evolutionId
        }
      );

      // 4. Update Supabase
      setErrorMessage(selectedTemplateId ? 'Etapa 5/5: Finalizando...' : 'Etapa 4/4: Finalizando...');
      const { error: updateError } = await supabase
        .from('evolutions')
        .update({
          transcription_status: 'completed',
          transcription_text: evolutionText,
          original_transcription_text: transcription,
          google_doc_append_status: 'completed',
          google_doc_append_at: new Date().toISOString(),
          updated_at: new Date().toISOString()
        })
        .eq('id', evolutionId);
      if (updateError) throw updateError;

      await clearSharedAudioSources();
      sessionStorage.removeItem(SHARE_TARGET_AUTH_RECOVERY_KEY);
      setModalEvolutionId(evolutionId);
      setModalText(evolutionText);
      setModalOriginalTranscription(transcription);
      setModalTemplateId(selectedTemplateId);
      setStatus('success');
      setErrorMessage('');

      // Dispara notificação in-app/push/email de sucesso para áudio compartilhado
      void sendNotification({
        title: "Áudio do WhatsApp Processado 🎙️",
        content: `A evolução do áudio compartilhado para ${patient?.full_name || 'Paciente'} foi criada e inserida no Google Docs com sucesso.`,
        type: "success",
        link: `/painel/patients/${selectedPatientId}`
      });

    } catch (error: any) {
      console.error("ERRO CRÍTICO NO SHARE TARGET:", error);
      let msg = error.message || "Erro desconhecido";

      if (msg === 'offline' || msg === 'Failed to fetch' || msg.includes('NetworkError')) {
        try {
          await addPendingEvolution({
            id: evolutionId,
            patientId: selectedPatientId,
            patientName: patient?.full_name || 'Paciente',
            googleDocId: patient?.google_doc_id || '',
            sessionDate,
            audioBlob: audioFile,
            mimeType: audioFile.type || 'audio/ogg',
            source: 'share',
            createdAt: new Date().toISOString(),
            evolutionData
          });

          await clearSharedAudioSources();
          setStatus('success');
          setErrorMessage('');
          alert("Sem internet! O áudio do WhatsApp foi salvo na sua Fila Offline e será enviado quando a conexão retornar.");
          return;
        } catch (queueErr) {
          console.error("Erro ao salvar offline:", queueErr);
          msg = "Você está sem internet e ocorreu um erro ao guardar na fila local.";
        }
      } else if (msg.includes('401') || msg.includes('UNAUTHENTICATED') || msg.includes('Credentials')) {
        msg = "Sua sessão do Google expirou. Por favor, renove a autenticação abaixo.";
        setGoogleAccessToken(null);
      } else if (msg.includes('timeout') || msg.includes('55s')) {
        msg = "O Google demorou demais para responder. Tente um áudio mais curto ou tente novamente.";
      }

      setErrorMessage(msg);
      setStatus('error');

      // Uma renovação do Google é um estado recuperável da conexão, não uma
      // segunda falha que precise gerar outra notificação para a pessoa usuária.
      if (!isGoogleReconnectNeededMessage(msg)) {
        void sendNotification({
          title: "Erro no Áudio Compartilhado ⚠️",
          content: `Falha ao processar áudio compartilhado para ${patient?.full_name || 'Paciente'}: ${msg}`,
          type: "error",
          link: `/painel/patients/${selectedPatientId}`
        });
      }

      // Update Supabase with error if possible
      try {
        await supabase
          .from('evolutions')
          .update({
            transcription_status: 'error',
            error_message: msg,
            updated_at: new Date().toISOString()
          })
          .eq('id', evolutionId);
      } catch (f) {
        console.error("Falha ao salvar erro no Supabase:", f);
      }
    }
  };

  if (status === 'loading') {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="h-8 w-8 text-brand-primary animate-spin" />
        <span className="ml-2 text-brand-text-muted">Carregando arquivo compartilhado...</span>
      </div>
    );
  }

  return (
    <div className="w-full">
      <PanelPageHeader
        icon={Mic}
        title="Áudio Recebido"
        description="Selecione o paciente para processar este áudio."
      />
      <div className="card overflow-hidden">
        <div className="mt-6 p-6 space-y-6">
          {status === 'success' ? (
            <div className="text-center py-8">
              <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-brand-accent/20 mb-4">
                <CheckCircle className="h-6 w-6 text-brand-primary" />
              </div>
              <h3 className="text-lg font-display font-medium text-brand-text mb-2">Evolução Processada!</h3>
              <p className="text-brand-text-muted mb-6">O áudio foi transcrito e inserido no Google Docs com sucesso.</p>

              {(() => {
                const patient = patients.find(p => p.id === selectedPatientId);
                if (patient && patient.google_doc_id) {
                  return (
                    <div className="flex flex-col sm:flex-row gap-3 w-full justify-center mt-4 mb-6 border-b border-brand-border/30 pb-6">
                      <a
                        href={`https://docs.google.com/document/d/${patient.google_doc_id}/edit`}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex items-center justify-center space-x-2 px-4 py-2.5 bg-white text-brand-primary border border-brand-primary/20 rounded-xl hover:bg-brand-primary/5 font-medium transition-colors text-sm w-full sm:w-auto"
                      >
                        <ExternalLink className="w-4 h-4" />
                        <span>Acessar Documento no Google Drive</span>
                      </a>
                      <button
                        onClick={handleOpenModal}
                        className="flex items-center justify-center space-x-2 px-4 py-2.5 bg-brand-primary/10 text-brand-primary rounded-xl hover:bg-brand-primary/20 font-medium transition-colors text-sm w-full sm:w-auto"
                      >
                        <Eye className="w-4 h-4" />
                        <span>Ver/Editar Evolução</span>
                      </button>
                    </div>
                  );
                }
                return null;
              })()}

              <div className="flex flex-col sm:flex-row items-center justify-center gap-3">
                <button
                  onClick={() => navigate(`/painel/patients/${selectedPatientId}`)}
                  className="btn-primary w-full sm:w-auto"
                >
                  Ver Perfil do Paciente
                </button>
                <button
                  onClick={() => navigate('/painel/dashboard')}
                  className="btn-outline w-full sm:w-auto"
                >
                  Ir para Home
                </button>
              </div>
            </div>
          ) : (
            <>
              {audioUrl && (
                <div className="bg-brand-bg p-4 rounded-xl border border-brand-border">
                  <p className="text-sm font-medium text-brand-text mb-2">Áudio Compartilhado:</p>
                  {useNativeAudioPlayer ? (
                    <div className="rounded-xl border border-brand-border bg-white p-3">
                      <div className="flex items-center gap-3">
                        <button
                          type="button"
                          data-native-audio-control="true"
                          onClick={handleNativePlaybackToggle}
                          className="flex h-11 w-11 shrink-0 items-center justify-center rounded-full bg-brand-primary text-white"
                          aria-label={nativePlaybackRequested ? 'Pausar áudio' : 'Reproduzir áudio'}
                        >
                          {nativePlaybackRequested ? (
                            <Pause className="h-5 w-5" />
                          ) : (
                            <Play className="h-5 w-5 translate-x-px" />
                          )}
                        </button>
                        <div className="min-w-0 flex-1">
                          <input
                            type="range"
                            min={0}
                            max={Math.max(nativePlayback.durationMs, 1)}
                            value={Math.min(nativePlayback.positionMs, Math.max(nativePlayback.durationMs, 1))}
                            onChange={(event) => handleNativePlaybackSeek(Number(event.target.value))}
                            disabled={nativePlayback.durationMs <= 0}
                            className="w-full accent-brand-primary"
                            aria-label="Posição do áudio"
                          />
                          <div className="flex justify-between text-xs text-brand-text-muted">
                            <span>{formatPlaybackTime(nativePlayback.positionMs)}</span>
                            <span>{formatPlaybackTime(nativePlayback.durationMs)}</span>
                          </div>
                        </div>
                      </div>
                      {nativePlayback.status === 'error' && (
                        <p className="mt-2 text-xs text-red-700">
                          {nativePlayback.error || 'Não foi possível reproduzir este áudio no aparelho.'}
                        </p>
                      )}
                    </div>
                  ) : (
                    <audio
                      ref={audioElementRef}
                      controls
                      preload="metadata"
                      className="w-full"
                      onCanPlay={() => setAudioPlaybackError(false)}
                      onLoadedMetadata={(event) => setAudioMetadataUnavailable(!Number.isFinite(event.currentTarget.duration) || event.currentTarget.duration <= 0)}
                      onError={() => setAudioPlaybackError(true)}
                    >
                      <source src={audioUrl} type={audioFile?.type} />
                    </audio>
                  )}
                  {needsNativePauseUpdate && useNativeAudioPlayer ? (
                    <p className="mt-2 text-xs font-medium text-amber-800">
                      Atualize o aplicativo para a versão 1.0.75 ou superior para usar a pausa garantida.
                    </p>
                  ) : audioPlaybackError && !useNativeAudioPlayer ? (
                    <p className="mt-2 text-xs text-amber-800">
                      Este navegador não conseguiu reproduzir a prévia, mas o áudio recebido continuará disponível para processamento.
                    </p>
                  ) : audioMetadataUnavailable ? (
                    <p className="mt-2 text-xs text-brand-text-muted">
                      A duração não foi identificada pelo player deste aparelho. Isso não impede o processamento da evolução.
                    </p>
                  ) : null}
                </div>
              )}

              <div>
                <label className="block text-sm font-medium text-brand-text mb-1">
                  Paciente
                </label>
                <select
                  value={selectedPatientId}
                  onChange={(e) => handlePatientChange(e.target.value)}
                  className="input-field p-2"
                  disabled={status === 'processing'}
                >
                  <option value="">Selecione um paciente...</option>
                  {patients.map((p) => (
                    <option key={p.id} value={p.id}>
                      {p.full_name}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-brand-text mb-1">
                  Template de Evolução
                </label>
                <select
                  value={selectedTemplateId}
                  onChange={(event) => setSelectedTemplateId(event.target.value)}
                  className="input-field p-2"
                  disabled={status === 'processing'}
                >
                  <option value="">Sem template (transcrição original)</option>
                  {templates.map(template => (
                    <option key={template.id} value={template.id}>
                      {template.name}
                    </option>
                  ))}
                </select>
                <p className="mt-1 text-xs text-brand-text-muted">
                  O template padrão do paciente é selecionado automaticamente e pode ser alterado antes do processamento.
                </p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-brand-text mb-1">
                    Data do Atendimento
                  </label>
                  <input
                    type="date"
                    value={sessionDate}
                    onChange={(e) => setSessionDate(e.target.value)}
                    className="input-field p-2"
                    disabled={status === 'processing'}
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-brand-text mb-1">
                    Hora do Atendimento
                  </label>
                  <input
                    type="time"
                    value={sessionTime}
                    onChange={(e) => handleSessionTimeChange(e.target.value)}
                    className="input-field p-2"
                    disabled={status === 'processing'}
                  />
                  <p className="mt-1 text-xs text-brand-text-muted">
                    Hora em que a sessão foi realizada.
                  </p>
                </div>
              </div>

              {!hasClinicalAccess && user && (
                <div className="bg-amber-50 border border-amber-200 rounded-xl p-4">
                  <div className="flex">
                    <AlertCircle className="h-5 w-5 text-amber-500 mt-0.5" />
                    <div className="ml-3 flex-1">
                      <h3 className="text-sm font-medium text-amber-900">Conexão Google indisponível</h3>
                      <p className="mt-1 text-sm text-amber-800">
                        A conexão com o Google expirou ou está sem as permissões clínicas completas.
                        Renove antes de processar o áudio.
                      </p>
                      <button
                        onClick={() => handleReauthenticate()}
                        disabled={isReauthenticating}
                        className="mt-3 inline-flex items-center px-3 py-1.5 border border-transparent text-xs font-medium rounded-lg text-amber-900 bg-amber-100 hover:bg-amber-200 transition-colors disabled:opacity-50"
                      >
                        {isReauthenticating ? (
                          <Loader2 className="h-4 w-4 mr-1.5 animate-spin" />
                        ) : (
                          <RefreshCw className="h-4 w-4 mr-1.5" />
                        )}
                        Renovar Autenticação do Google
                      </button>
                    </div>
                  </div>
                </div>
              )}

              {status === 'error' && !needsGoogleReconnect && (
                <div className="bg-red-50 border border-red-200 rounded-xl p-4">
                  <div className="flex">
                    <AlertCircle className="h-5 w-5 text-red-400" />
                    <div className="ml-3">
                      <h3 className="text-sm font-medium text-red-800">Erro no processamento</h3>
                      <div className="mt-2 text-sm text-red-700">
                        <p>{errorMessage}</p>
                      </div>
                    </div>
                  </div>
                </div>
              )}

              <div className="pt-4 flex justify-end gap-3">
                <button
                  type="button"
                  onClick={handleCancel}
                  disabled={status === 'processing'}
                  className="btn-outline disabled:opacity-50"
                >
                  Cancelar
                </button>
                <button
                  onClick={handleProcess}
                  disabled={status === 'processing' || !selectedPatientId || !audioFile}
                  className="btn-primary disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {status === 'processing' ? (
                    <>
                      <Loader2 className="animate-spin -ml-1 mr-2 h-4 w-4" />
                      {errorMessage || 'Processando...'}
                    </>
                  ) : (
                    <>
                      <Upload className="-ml-1 mr-2 h-4 w-4" />
                      Processar Evolução
                    </>
                  )}
                </button>
              </div>
              {!selectedPatientId && audioFile && (
                <p className="text-right text-xs text-brand-text-muted">Selecione um paciente para liberar o processamento.</p>
              )}
            </>
          )}
        </div>
      </div>

      {/* Modal de visualização/edição */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[90] overflow-y-auto overscroll-y-contain bg-stone-900/60 p-4 transition-opacity sm:flex sm:items-center sm:justify-center">
          <div className="relative z-[91] mx-auto my-2 flex min-h-[70vh] max-h-[calc(100dvh-2rem)] w-full max-w-2xl min-w-0 flex-col overflow-hidden rounded-2xl border border-brand-border bg-white shadow-xl animate-in fade-in zoom-in-95 duration-200 sm:my-0 sm:max-h-[85vh]">
            {/* Modal Header */}
            <div className="flex items-center justify-between px-6 py-4 border-b border-brand-border">
              <div>
                <h3 className="text-lg font-bold font-display text-brand-primary">
                  Editar Evolução Processada
                </h3>
                <p className="text-xs text-brand-text-muted mt-0.5">
                  {patients.find(p => p.id === selectedPatientId)?.full_name}
                </p>
              </div>
              <button
                onClick={() => setIsModalOpen(false)}
                className="p-1.5 rounded-lg text-brand-text-muted hover:bg-stone-100 hover:text-brand-text transition-colors"
                disabled={modalSaving || modalConverting}
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            {/* Modal Content */}
            <div className="min-h-0 flex-1 overflow-y-auto p-6 space-y-4">
              {modalError ? (
                <div className="p-4 bg-red-50 rounded-xl border border-red-100 text-center space-y-3">
                  <AlertCircle className="w-8 h-8 text-red-600 mx-auto" />
                  <p className="text-sm text-red-700 font-medium">{modalError}</p>
                  {needsGoogleReconnect && (
                    <button
                      onClick={() => handleReauthenticate()}
                      className="px-4 py-2 bg-red-600 text-white rounded-xl hover:bg-red-700 text-sm font-medium transition-colors"
                    >
                      Renovar Autenticação
                    </button>
                  )}
                  {hasClinicalAccess && (
                    <button
                      onClick={handleOpenModal}
                      className="px-4 py-2 bg-stone-800 text-white rounded-xl hover:bg-stone-700 text-sm font-medium transition-colors"
                    >
                      Tentar Novamente
                    </button>
                  )}
                </div>
              ) : (
                  <div className="space-y-3">
                    <div className="rounded-xl border border-brand-primary/15 bg-brand-primary/5 p-3">
                      <label className="mb-1 block text-xs font-semibold text-brand-text">Converter para outro modelo</label>
                      <div className="flex flex-col gap-2 sm:flex-row">
                        <select
                          value={modalTemplateId}
                          onChange={(event) => setModalTemplateId(event.target.value)}
                          disabled={modalSaving || modalConverting}
                          className="input-field min-w-0 flex-1 py-2 text-sm"
                        >
                          <option value="">Sem template (transcrição original)</option>
                          {templates.map((template) => <option key={template.id} value={template.id}>{template.name}</option>)}
                        </select>
                        <button
                          type="button"
                          onClick={() => void handleConvertModalEvolution()}
                          disabled={modalSaving || modalConverting}
                          className="btn-outline shrink-0 border-brand-primary/30 text-brand-primary disabled:opacity-50"
                        >
                          {modalConverting ? <Loader2 size={15} className="animate-spin" /> : <RefreshCw size={15} />}
                          <span>{modalConverting ? 'Convertendo...' : 'Converter'}</span>
                        </button>
                      </div>
                      <p className="mt-2 text-[11px] text-brand-text-muted">Os modelos são aplicados sobre a transcrição original. Ao escolher sem template, o texto original é restaurado sem usar IA.</p>
                    </div>
                    <RichTextEditor
                      value={modalText}
                      onChange={setModalText}
                      label="Conteúdo da evolução"
                      disabled={modalSaving || modalConverting}
                    />
                    <p className="text-[11px] text-brand-text-muted">
                      Nota: ao salvar, somente esta evolução e suas formatações serão atualizadas no Google Docs.
                    </p>
                </div>
              )}
            </div>

            {/* Modal Footer */}
            {!modalError && (
              <div className="app-safe-bottom-padding flex shrink-0 flex-wrap items-center justify-end gap-3 border-t border-brand-border bg-stone-50 px-6 py-4 sm:flex-nowrap sm:space-x-3 sm:pb-4">
                <button
                  onClick={() => setIsModalOpen(false)}
                  className="px-4 py-2 bg-white border border-brand-border rounded-xl text-sm font-medium text-brand-text hover:bg-stone-100 transition-colors"
                  disabled={modalSaving || modalConverting}
                >
                  Cancelar
                </button>
                <button
                  onClick={handleSaveModalText}
                  className="flex items-center space-x-2 px-4 py-2 bg-brand-primary hover:bg-brand-primary-hover disabled:opacity-50 text-white rounded-xl text-sm font-medium transition-colors"
                  disabled={modalSaving || modalConverting}
                >
                  {modalSaving ? (
                    <>
                      <Loader2 className="w-4 h-4 animate-spin" />
                      <span>Salvando...</span>
                    </>
                  ) : (
                    <>
                      <Save className="w-4 h-4" />
                      <span>Salvar Alterações</span>
                    </>
                  )}
                </button>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

