export type AcquisitionTelemetryEvent =
  | 'acquisition_arrival'
  | 'consent_banner_shown'
  | 'marketing_consent_granted'
  | 'meta_config_loaded'
  | 'meta_config_failed'
  | 'meta_script_requested'
  | 'meta_pixel_initialized'
  | 'meta_pageview_queued';

export type AcquisitionTelemetryContext = {
  pathname?: string;
  channel?: string;
  campaignPresent?: boolean;
  platform?: 'web' | 'pwa' | 'android';
  distribution?: 'google_play';
  dedupeKey?: string;
};

const sentKeys = new Set<string>();
const EVENT_NAMES = new Set<AcquisitionTelemetryEvent>([
  'acquisition_arrival',
  'consent_banner_shown',
  'marketing_consent_granted',
  'meta_config_loaded',
  'meta_config_failed',
  'meta_script_requested',
  'meta_pixel_initialized',
  'meta_pageview_queued'
]);
const PUBLIC_ACQUISITION_PATHS = new Set(['/','/login','/jornada','/jornada-15-dias']);

export const isPublicAcquisitionPathname = (pathname: string) => {
  const normalized = pathname.trim() || '/';
  return PUBLIC_ACQUISITION_PATHS.has(normalized) || normalized.startsWith('/jornada/');
};

const normalizePathname = (pathname?: string) => {
  const value = (pathname || (typeof window !== 'undefined' ? window.location.pathname : '/')).split(/[?#]/, 1)[0] || '/';
  return value.replace(/[^A-Za-z0-9/_-]/g, '').slice(0, 120) || '/';
};

const normalizeChannel = (channel?: string) => {
  const value = (channel || '').toLowerCase();
  if (value.includes('google ads')) return 'google_ads';
  if (value.includes('meta ads') || value.includes('facebook') || value.includes('instagram')) return 'meta_ads';
  if (value.includes('google')) return 'google_organic';
  if (value.includes('youtube')) return 'youtube';
  if (value.includes('whatsapp')) return 'whatsapp';
  if (value.includes('e-mail')) return 'email';
  if (value.includes('referral')) return 'referral';
  if (value.includes('direto')) return 'direct';
  return value ? 'other' : 'unknown';
};

export const sendAcquisitionTelemetry = (eventName: AcquisitionTelemetryEvent, context: AcquisitionTelemetryContext = {}) => {
  if (!EVENT_NAMES.has(eventName) || typeof window === 'undefined' || typeof window.fetch !== 'function') return false;
  const dedupeKey = context.dedupeKey || `${eventName}:${normalizePathname(context.pathname)}`;
  if (sentKeys.has(dedupeKey)) return false;
  sentKeys.add(dedupeKey);

  const payload = {
    eventName,
    pathname: normalizePathname(context.pathname),
    channel: normalizeChannel(context.channel),
    campaignPresent: context.campaignPresent === true,
    platform: context.platform,
    distribution: context.distribution
  };
  void window.fetch('/api/analytics/acquisition-telemetry', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(payload),
    keepalive: true
  }).catch(() => undefined);
  return true;
};

export const resetAcquisitionTelemetryForTests = () => sentKeys.clear();

src/services/aiTranscription.ts:
import { supabase } from "../supabaseClient";
import { getAudioDurationFromBlob } from "../utils/audioDuration";
import { getAudioLimitPolicy, type AudioSubscriptionPlan } from "../utils/audioLimits";

export interface TranscriptionOptions {
  audioBlob: Blob;
  mimeType: string;
  fileName?: string;
  onRetry?: (attempt: number, delay: number, isFallback: boolean) => void;
  audioDuration?: number; // em segundos
  customPrompt?: string;
  subscriptionPlan?: AudioSubscriptionPlan;
  evolutionId: string;
  audioKey: string;
}

const DEFAULT_TRANSCRIPTION_PROMPT = `Transcreva integralmente este áudio clínico em português do Brasil, preservando o sentido do relato da terapeuta ocupacional. Corrija apenas vícios de fala, repetições desnecessárias e ruídos de linguagem. Não invente informações. Retorne somente a transcrição final em texto corrido, sem títulos, sem cabeçalhos, sem resumos, sem contexto adicional, sem explicações, sem listas e sem qualquer frase de abertura ou encerramento.`;

export const resolveAudioMimeType = (mimeType?: string, fileName?: string): string => {
  let normalizedMimeType = (mimeType || '').toLowerCase();

  if (normalizedMimeType.includes(';')) {
    normalizedMimeType = normalizedMimeType.split(';')[0].trim();
  }

  const extension = String(fileName || '').trim().toLowerCase().split('.').pop();
  if (
    extension === 'ogg' ||
    extension === 'oga' ||
    extension === 'opus' ||
    normalizedMimeType === 'audio/ogg' ||
    normalizedMimeType === 'audio/x-ogg' ||
    normalizedMimeType === 'application/ogg' ||
    normalizedMimeType === 'application/x-ogg' ||
    normalizedMimeType === 'audio/opus'
  ) {
    return 'audio/ogg';
  }

  if (extension === 'mp3') return 'audio/mpeg';
  if (extension === 'wav') return 'audio/wav';
  if (extension === 'm4a' || extension === 'mp4') return 'audio/mp4';
  if (extension === 'aac') return 'audio/aac';
  if (extension === 'webm' || extension === 'weba') return 'audio/webm';

  if (!normalizedMimeType || normalizedMimeType === 'application/octet-stream') {
    return 'audio/webm';
  }

  return normalizedMimeType;
};

const getAudioExtension = (mimeType: string): string => {
  const normalized = mimeType.toLowerCase();

  if (normalized.includes('webm')) return 'webm';
  if (normalized.includes('ogg')) return 'ogg';
  if (normalized.includes('mpeg')) return 'mp3';
  if (normalized.includes('mp4') || normalized.includes('m4a')) return 'm4a';
  if (normalized.includes('wav')) return 'wav';
  if (normalized.includes('aac')) return 'aac';

  const subtype = normalized.includes('/') ? normalized.split('/')[1] : normalized;
  const sanitized = subtype.split(';')[0].replace(/[^a-z0-9]+/g, '');
  return sanitized || 'bin';
};

const buildTempAudioPath = (userId: string, mimeType: string): string => {
  const timestamp = Date.now();
  const randomPart = globalThis.crypto?.randomUUID?.().replace(/-/g, '') || Math.random().toString(36).slice(2, 10);
  const extension = getAudioExtension(mimeType);

  return `${userId}/${timestamp}-${randomPart}.${extension}`;
};

const isBucketMissingError = (message: string): boolean => {
  const normalized = message.toLowerCase();
  return (
    normalized.includes('bucket not found') ||
    normalized.includes('nosuchbucket') ||
    normalized.includes('temp-audio')
  );
};

const isModelConfigurationError = (message: string): boolean => {
  const normalized = message.toLowerCase();
  return (
    normalized.includes('not found for api version') ||
    normalized.includes('not supported for generatecontent') ||
    normalized.includes('model') && normalized.includes('not found') ||
    normalized.includes('models/')
  );
};

const isHardLimitError = (message: string): boolean => {
  const normalized = message.toLowerCase();
  return (
    normalized.includes('(http 400)') ||
    normalized.includes('(http 403)') ||
    normalized.includes('limite máximo de 20 minutos') ||
    normalized.includes('limite máximo de 60 minutos') ||
    normalized.includes('tamanho máximo permitido de 20 mb') ||
    normalized.includes('arquivo de áudio pode ter no máximo 20 mb') ||
    normalized.includes('arquivo de áudio pode ter no máximo 60 mb') ||
    normalized.includes('muitas solicitações de transcrição') ||
    normalized.includes('limite mensal de transcrição de áudio atingido') ||
    normalized.includes('duração do áudio é obrigatória')
  );
};

export const transcribeAudio = async (options: TranscriptionOptions): Promise<string> => {
  const { audioBlob, mimeType, fileName, onRetry, audioDuration, customPrompt, subscriptionPlan, evolutionId, audioKey } = options;
  const audioPolicy = getAudioLimitPolicy(subscriptionPlan);
  const maxRetries = 3;
  let retryCount = 0;
  const normalizedMimeType = resolveAudioMimeType(mimeType || audioBlob.type, fileName);
  const prompt = customPrompt || DEFAULT_TRANSCRIPTION_PROMPT;

  if (!evolutionId || !audioKey) {
    throw new Error("Não foi possível identificar a evolução e o áudio para validar o limite.");
  }

  if (typeof audioDuration === 'number' && Number.isFinite(audioDuration) && audioDuration > audioPolicy.maxDurationSeconds) {
    throw new Error(`O áudio excede o limite máximo de ${audioPolicy.maxDurationSeconds / 60} minutos por evolução.`);
  }

  if (audioBlob.size > audioPolicy.maxFileBytes) {
    throw new Error(`O arquivo de áudio pode ter no máximo ${Math.round(audioPolicy.maxFileBytes / 1024 / 1024)} MB.`);
  }

  // O seletor de arquivos do Android pode devolver um File vinculado a um
  // content:// URI temporário. O WebView consegue lê-lo, mas pode falhar ao
  // usá-lo diretamente como corpo de uma segunda requisição. Materializar os
  // bytes torna o upload independente desse URI e mantém o conteúdo original.
  const audioBytes = new Uint8Array(await audioBlob.arrayBuffer());

  if (audioBytes.byteLength === 0) {
    throw new Error("O arquivo de áudio selecionado está vazio ou não pôde ser lido neste dispositivo.");
  }

  const detectedAudioDuration = typeof audioDuration === 'number' && Number.isFinite(audioDuration) && audioDuration > 0
    ? audioDuration
    : await getAudioDurationFromBlob(audioBlob);

  if (!detectedAudioDuration || !Number.isFinite(detectedAudioDuration)) {
    throw new Error("Não foi possível identificar a duração do áudio. Reproduza o arquivo ou selecione-o novamente antes de processar.");
  }

  if (detectedAudioDuration > audioPolicy.maxDurationSeconds) {
    throw new Error(`O áudio excede o limite máximo de ${audioPolicy.maxDurationSeconds / 60} minutos por evolução.`);
  }

  const audioDurationSeconds = Math.max(1, Math.ceil(detectedAudioDuration));

  const attemptTranscription = async (): Promise<string> => {
    let requestStage: 'upload' | 'transcription' = 'upload';
    try {
      const { data: { session } } = await supabase.auth.getSession();
      const token = session?.access_token;
      const userId = session?.user?.id;

      if (!token) {
        throw new Error("Usuário não autenticado. Faça login novamente.");
      }

      if (!userId) {
        throw new Error("Não foi possível identificar o usuário autenticado.");
      }

      const audioPath = buildTempAudioPath(userId, normalizedMimeType);

      console.log(`[AI-Service] Enviando áudio para transcrição via Storage + backend - Tentativa ${retryCount + 1}`);

      const { error: uploadError } = await supabase.storage.from('temp-audio').upload(audioPath, audioBytes, {
        contentType: normalizedMimeType,
        upsert: false,
        cacheControl: '60',
      });

      if (uploadError) {
        const uploadErrorMessage = uploadError.message || JSON.stringify(uploadError);
        if (isBucketMissingError(uploadErrorMessage)) {
          throw new Error(`Bucket temp-audio não encontrado no Supabase Storage. Aplique a migration do bucket antes de tentar transcrever.`);
        }
        throw uploadError;
      }

      requestStage = 'transcription';
      const response = await fetch('/api/ai/transcribe', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          audioPath,
          mimeType: normalizedMimeType,
          prompt,
          audioDuration: audioDurationSeconds,
          evolutionId,
          audioKey
        })
      });

      const responseText = await response.text();
      let data: any = {};
      if (responseText) {
        try {
          data = JSON.parse(responseText);
        } catch {
          data = { error: responseText };
        }
      }

      if (!response.ok) {
        const serverError = new Error(`${data.error || 'Erro do servidor'} (HTTP ${response.status})`) as Error & { code?: string };
        serverError.code = typeof data.code === 'string' ? data.code : undefined;
        throw serverError;
      }

      if (!data.success || !data.transcription) {
        throw new Error("Resposta de transcrição inválida obtida do servidor.");
      }

      console.log("[AI-Service] Transcrição via backend concluída com sucesso.");
      return data.transcription;

    } catch (error: any) {
      const errorContent = error.message || JSON.stringify(error);
      const normalizedErrorContent = errorContent.toLowerCase();
      const isQuotaError = normalizedErrorContent.includes('quota') ||
                           normalizedErrorContent.includes('exhausted') ||
                           normalizedErrorContent.includes('resource_exhausted');
      const isBucketError = isBucketMissingError(errorContent);
      const isModelError = isModelConfigurationError(errorContent);
      const isPolicyError = isHardLimitError(errorContent) || [
        'AUDIO_REQUEST_INVALID',
        'AUDIO_DURATION_UNAVAILABLE',
        'AUDIO_EVOLUTION_DURATION_LIMIT',
        'AUDIO_FILE_SIZE_LIMIT',
        'AUDIO_MONTHLY_QUOTA_LIMIT',
        'AUDIO_ALREADY_PROCESSED',
        'AUDIO_PROCESSING_IN_PROGRESS',
      ].includes(error?.code);

      console.error("[AI-Service] Erro na transcrição:", errorContent);

      if (!isBucketError && !isModelError && !isPolicyError && retryCount < maxRetries) {
        retryCount++;
        // Se for erro de cota, aumenta o delay (mínimo 15 segundos)
        const delay = isQuotaError ? 15000 * retryCount : 2000 * retryCount;

        console.log(`[AI-Service] Tentando re-executar em ${delay}ms...`);

        if (onRetry) {
          onRetry(retryCount, delay, isQuotaError);
        }

        await new Promise(resolve => setTimeout(resolve, delay));
        return attemptTranscription();
      }

      if (isBucketError) {
        throw new Error(`${errorContent} (O bucket temp-audio precisa existir no Supabase Storage)`);
      }

      if (isModelError) {
        throw new Error(`${errorContent} (O modelo configurado para transcrição não é compatível com este endpoint)`);
      }

      if (normalizedErrorContent.includes('failed to fetch') || normalizedErrorContent.includes('networkerror')) {
        const stageDescription = requestStage === 'upload'
          ? 'Não foi possível enviar o arquivo de áudio selecionado para o armazenamento seguro.'
          : 'A conexão foi interrompida enquanto o áudio era enviado para transcrição.';
        throw new Error(`${stageDescription} Verifique a conexão e tente novamente.`);
      }

      throw new Error(`${errorContent} (Erro na comunicação com o backend de transcrição)`);
    }
  };

  return attemptTranscription();
};

